argv:
$ErrorActionPreference='Continue'
$o=[ordered]@{}
try {
 $s=Invoke-RestMethod 'http://127.0.0.1:8080/api/status' -TimeoutSec 4
 $err=[string]$s.tunnel_metadata_error
 $patterns=[ordered]@{
   missingUse='(?i)(tunnel[\. _\-]?use|api\.organization\.tunnel\.use|missing[^\r\n]{0,60}permission)'
   noTunnel='(?i)(tunnel[^\r\n]{0,60}(not found|not exist|unknown))'
   orgDenied='(?i)(organization[^\r\n]{0,80}(denied|mismatch|not found|unauthorized|forbidden))'
   workspaceDenied='(?i)(workspace[^\r\n]{0,80}(denied|mismatch|not found|unauthorized|forbidden|access))'
   accessDenied='(?i)(access denied|not authorized|forbidden|permission denied|does not have permission)'
   expired='(?i)(expired|expiration)'
   blocked='(?i)(not enabled|not entitled|unsupported|not available)'
   project='(?i)(project)'
   scope='(?i)(scope)'
   platformResponse='(?i)(HTTP 403|status.?code.?403)'
 }
 $o.errorPatternMatches=@($patterns.Keys|Where-Object { $err -match $patterns[$_] })
 $o.errorLength=$err.Length
 $o.metadataErrorKind=if($err -match '(?i)metadata'){'metadata'}else{'unspecified'}
 $o.channelsCount=@($s.channels).Count
 $o.routesCount=@($s.mcp_routes).Count
 $o.tunnelIdMatches=($s.control_plane_tunnel_id -eq 'tunnel_6ac88c3d680c8191a475065208874b7c')
}catch{$o.status='unavailable'}
try {
 $m=(Invoke-WebRequest 'http://127.0.0.1:8080/metrics' -UseBasicParsing -TimeoutSec 3).Content
 $lines=@($m -split [char]10|Where-Object{$_ -match '^commands_poll_(errors_total|cycles_total)\{'}|Select-Object -First 15)
 $o.pollErrCategories=@($lines|ForEach-Object{
   $z=[regex]::Match($_,'(?:code|status|reason|error|kind)="([^"]{1,80})"')
   if($z.Success){[regex]::Replace($z.Groups[1].Value,'[^a-zA-Z0-9_-]','_')}else{'unlabelled'}
 }|Sort-Object -Unique)
}catch{$o.metricStatus='unavailable'}
$o|ConvertTo-Json -Compress -Depth 5
